import { memo, useCallback, useMemo, useState } from "react";

type Product = { id: string; name: string };

const ProductRow = memo(function ProductRow({ product, onSelect }: {
  product: Product;
  onSelect: (id: string) => void;
}) {
  return <button onClick={() => onSelect(product.id)}>{product.name}</button>;
});

function ProductList({ products }: { products: Product[] }) {
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const visibleProducts = useMemo(
    () => products.filter((product) => product.name.toLowerCase().includes(query.toLowerCase())),
    [products, query],
  );
  const handleSelect = useCallback((id: string) => setSelectedId(id), []);
  return <>{visibleProducts.map((product) => <ProductRow key={product.id} product={product} onSelect={handleSelect} />)}</>;
}

import { lazy, Suspense } from "react";

const AnalyticsPage = lazy(() => import("./AnalyticsPage"));

function AnalyticsRoute() {
  return (
    <Suspense fallback={<p>Загрузка аналитики…</p>}>
      <AnalyticsPage />
    </Suspense>
  );
}

function SaveStatus({ saved }: { saved: boolean }) {
  return (
    <p role="status" aria-live="polite">
      {saved ? "Изменения сохранены." : "Есть несохранённые изменения."}
    </p>
  );
}

type Product = {
  id: string;
  name: string;
  imageUrl: string;
  imageAlt: string; // Empty only when the image adds no information
  isFavorite: boolean;
};

export function ProductCard({ product, onToggleFavorite }: {
  product: Product;
  onToggleFavorite: () => void;
}) {
  return (
    <article>
      <h2>{product.name}</h2>
      <img src={product.imageUrl} alt={product.imageAlt} />
      <button
        type="button"
        aria-label={`Favorite ${product.name}`}
        aria-pressed={product.isFavorite}
        onClick={onToggleFavorite}
      >
        ♥
      </button>
    </article>
  );
}

